1103	// SharedArrayBuffer or a byte view over one, anywhere in the saved graph),
1104	// or a return value that cannot be structured-cloned all count as a failed
1105	// attempt. Shared memory is rejected explicitly: cloning it "succeeds" but
1106	// keeps sharing the underlying bytes with an object the implementation can
1107	// still mutate, so no independent saved copy is possible. On success the
1108	// recorded value is a clone independent of any object the implementation
1109	// keeps holding. Attempts are numbered from 1, the wait after a failure
1110	// follows the configured backoff (zero stays zero, nothing is awaited after
1111	// the last attempt), and each actual invocation appends exactly one record,
1112	// in order, via collect.
1113	//
1114	// The two callers differ only through the hooks:
1115	// - prepareArgs(attempt) builds this attempt's fresh argument copies;
1116	// - invoke is the registered implementation, called as invoke(...args);
1117	// - createRecord(attempt) shapes the record (business attempts carry no
1118	//   operation/result fields, compensation attempts do);
1119	// - cloneFailureMessage names the operation kind for uncloneable returns;
1120	// - sharedMemoryFailureMessage names it for returns that contain shared
1121	//   memory, which cannot be isolated even though they clone;
1122	// - collect appends to the caller's own attempt list;
1123	// - onSuccess stores caller-specific success data on the record.
1124	// When a cancellation signal is given, no new attempt starts once it has
1125	// fired — even with a zero retry delay — and a wait in progress ends early;
1126	// an attempt already running is always awaited and its outcome recorded.
1127	// Compensation passes no signal and is therefore never interrupted.
1128	async function runWithRetries({
1129	  retry, signal = null, prepareArgs, invoke, createRecord,
1130	  cloneFailureMessage, sharedMemoryFailureMessage, collect, onSuccess,
1131	}) {
1132	  let lastReason = null;
1133	
1134	  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
1135	    if (signal && signal.aborted) {
1136	      return { ok: false, cancelled: true, error: lastReason };
1137	    }
1138	    const args = prepareArgs(attempt);
1139	    const record = createRecord(attempt);
1140	    let returned;
1141	    try {
1142	      returned = await invoke(...args);
1143	    } catch (error) {
1144	      lastReason = describeError(error);
1145	      record.error = lastReason;
1146	    }
1147	
1148	    // Clone first, then judge the clone: the isolation check must reflect
1149	    // exactly the content that will be saved. Inspecting the original return
1150	    // value would read enumerable getters an extra time (a getter that
1151	    // changes its answer between reads could swap ordinary saved content for
1152	    // later-appearing shared memory, or vice versa) and would iterate Map/Set
1153	    // through a possibly-overridden Symbol.iterator, while structuredClone
1154	    // reads the real internal entries. A return value whose normal reads
1155	    // throw, or that cannot be cloned at all, is the ordinary uncloneable
1156	    // failure — never an exception escaping the run.
1157	    if (record.error === null) {
1158	      try {
1159	        returned = structuredClone(returned);
1160	      } catch (error) {
1161	        lastReason = cloneFailureMessage;
1162	        record.error = lastReason;
1163	      }
1164	    }
1165	
1166	    if (record.error === null && containsSharedMemory(returned)) {
1167	      lastReason = sharedMemoryFailureMessage;
1168	      record.error = lastReason;
1169	    }
1170	
1171	    if (record.error === null) {
