1179	    // failure record but stops the retry loop: no wait, no next attempt —
1180	    // even when this was the last attempt the run could have made.
1181	    if (signal && signal.aborted) {
1182	      collect(record);
1183	      return { ok: false, cancelled: true, error: lastReason };
1184	    }
