1226	async function runCompensation(entry, implementation, records) {
1227	  const { nodeId, binding, snapshot } = entry;
1228	  return runWithRetries({
1229	    retry: binding.compensation.retry,
1230	    prepareArgs: attempt => [
1231	      structuredClone(snapshot.input), structuredClone(snapshot.output),
1232	      structuredClone(snapshot.result), nodeId, attempt,
1233	    ],
1234	    invoke: implementation,
1235	    createRecord: attempt => ({
1236	      nodeId, operation: binding.compensation.name, attempt,
1237	      ok: false, error: null, nextDelayMs: 0, result: null,
1238	    }),
1239	    cloneFailureMessage: `compensation "${binding.compensation.name}" returned a value that cannot be structured-cloned`,
