1264	// Scheduling state shared by the synchronous and asynchronous execution
1265	// loops: activation, completion, dependency gating and the recorded end
1266	// result all behave identically; only business-action handling differs.
1267	//
1268	// The caller input is received — cloned and checked for retained shared
1269	// memory — here, the single point every entry passes through before any node
1270	// can run. Both entries call this after the definition, cancellation-option
1271	// and operation-registration checks but (for the asynchronous entry) before
1272	// the already-aborted-at-start short-circuit, so a shared-memory input is
1273	// rejected with a TypeError even when the signal has already fired.
1274	function createRunState(nodes, workflow, input) {
1275	  const declarationOrder = [...nodes.values()];
1276	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
1277	  return {
1278	    trace: [],
1279	    actionAttempts: [],
1280	    context: { input: cloneRunInput(input), output: {} },
1281	    declarationOrder,
1282	    declarationIndex,
1283	    activated: new Set([workflow.entry]),
1284	    completed: new Set(),
1285	    endReached: false,
1286	    endResult: null,
1287	    // Successful business actions that declared a compensation, in the order
1288	    // they succeeded. Each entry keeps independent snapshots captured at the
1289	    // action's own success moment.
1290	    compensable: [],
