1329	    if (waiting) return { kind: 'blocked', waiting };
1330	    if (state.endReached) return { kind: 'completed' };
1331	    throw new Error('workflow did not terminate; a cycle is present');
1332	  }
1333	  state.trace.push({ nodeId: ready.id, type: ready.type });
