1432	export function executeWorkflow(workflow, input = {}) {
1433	  const nodes = validateWorkflow(workflow);
1434	  // Business operations are asynchronous: the synchronous entry must refuse
1435	  // a workflow that names any before a single node executes.
1436	  for (const node of nodes.values()) {
1437	    const binding = actionBindings.get(node);
1438	    if (binding && binding.name !== null) {
1439	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1440	    }
1441	  }
1442	
1443	  const state = createRunState(nodes, workflow, input);
1444	
1445	  for (;;) {
1446	    const step = advanceSchedule(state);
1447	
1448	    if (step.kind === 'blocked') {
1449	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1450	    }
1451	    if (step.kind === 'completed') {
1452	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1453	    }
1454	    if (step.kind === 'end') continue;
1455	
1456	    const early = applyRegularNode(step.node, state);
