1461	// Attaches compensation results to a failed run. Successful outputs and the
1462	// original terminal status stay untouched; compensation records live on
1463	// their own fields, never in the regular node trace.
1464	async function withCompensation(result, state, operations) {
1465	  const outcome = await compensateRun(state, operations);
1466	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1467	  result.compensationAttempts = outcome.attempts;
