1512	        status: 'blocked', context: state.context, trace: state.trace,
1513	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1514	      }, state, operations);
1515	    }
1516	    if (step.kind === 'completed') {
1517	      // A completed run never invokes compensation.
1518	      return {
1519	        status: 'completed', result: state.endResult, context: state.context,
1520	        trace: state.trace, actionAttempts: state.actionAttempts,
1521	        compensationStatus: 'not_needed', compensationAttempts: [],
1522	      };
1523	    }
1524	    if (step.kind === 'end') continue;
1525	
1526	    const ready = step.node;
1527	    if (ready.type === 'action') {
1528	      const binding = actionBindings.get(ready);
1529	      if (binding.name !== null) {
1530	        // Nodes execute one at a time in declaration order; awaiting here
1531	        // never lets another node jump ahead.
1532	        const actionResult = await runBusinessAction(
1533	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1534	        if (!actionResult.ok) {
